here = Path(__file__).parent
for lang, lines in L.items():
    assert len(lines) == 41, (lang, len(lines))
    d = {"voice": VOICES[lang], "rate": "+0%"}
    if lang in NOTE:
        d["note"] = NOTE[lang]
    d["segments"] = {f"s{i + 1:02}": t for i, t in enumerate(lines)}
    (here / f"{lang}.json").write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    print(lang, len(lines))
